const HTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>TWP-CF Deployer</title><style>
:root{color-scheme:dark;--bg:#0b0e13;--bg2:#0f141b;--panel:#141a22;--panel2:#10151c;--field:#0a0e13;--line:#29323e;--line2:#3a4858;--text:#e7edf4;--muted:#8a96a5;--blue:#4d9fff;--blue2:#79b8ff;--green:#46d98b;--red:#ff6570}
*{box-sizing:border-box}
html{background:var(--bg)}
body{margin:0;min-height:100vh;background:linear-gradient(180deg,#0a0d12 0,#0d1117 45%,#0a0d12 100%);color:var(--text);font:14px/1.6 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace}
body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.16;background:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);background-size:32px 32px}
.wrap{width:min(760px,calc(100% - 28px));margin:0 auto;padding:32px 0 42px;position:relative}
.top{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:18px;padding:13px 15px;background:#10151c;border:1px solid var(--line);border-radius:8px;box-shadow:0 12px 35px rgba(0,0,0,.24)}
.brand{display:flex;align-items:center;gap:11px}.logo{width:35px;height:35px;display:grid;place-items:center;border:1px solid #354252;border-radius:7px;background:#0a0e13;color:var(--blue2);box-shadow:inset 0 1px rgba(255,255,255,.04)}.logo svg{width:19px;height:19px}.brand h1{margin:0;font-size:16px;line-height:1.1}.brand p{margin:4px 0 0;color:var(--muted);font-size:10px}.state{display:flex;align-items:center;gap:7px;color:#9aa6b5;font-size:10px}.state i{width:6px;height:6px;border-radius:50%;background:var(--green);box-shadow:0 0 9px rgba(70,217,139,.55)}
h2{font-size:18px;margin:18px 0 3px}.intro{color:var(--muted);font-size:11px;margin:0 0 13px}
.card{position:relative;background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:18px;margin-bottom:12px;box-shadow:0 13px 35px rgba(0,0,0,.22)}.card:before{content:"";position:absolute;left:-1px;top:10px;bottom:10px;width:2px;background:var(--blue);opacity:.75;border-radius:2px}
.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:0 0 11px;margin-bottom:14px;border-bottom:1px solid #252e39;color:#b6c0cc;font-size:9px;letter-spacing:.08em}.sectionhead span{color:#5f6c7b;font-size:8px;letter-spacing:.04em}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{min-width:0}.full,.wide{grid-column:1/-1}.label{display:flex;align-items:center;justify-content:space-between;gap:10px;color:#aeb8c5;font-size:10px;text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px}.hint{color:#6f7b8a;font-size:9px;text-transform:none;letter-spacing:0}.link{color:#06111e;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;min-height:30px;padding:0 12px;border:1px solid #5aa8ff;border-radius:5px;background:#4d9fff;font:600 9px ui-monospace,SFMono-Regular,Menlo,monospace;box-shadow:0 4px 14px rgba(77,159,255,.14);transition:filter .15s,transform .15s}.link:hover{filter:brightness(1.08);transform:translateY(-1px)}
.input,.select{width:100%;height:40px;padding:0 11px;background:var(--field);border:1px solid var(--line);border-radius:5px;color:var(--text);font:12px ui-monospace,SFMono-Regular,Menlo,monospace;outline:none;transition:border-color .16s,box-shadow .16s,background .16s}.input::placeholder{color:#566271}.input:hover,.select:hover{border-color:#3b4858}.input:focus,.select:focus{border-color:var(--blue);box-shadow:0 0 0 2px rgba(77,159,255,.12);background:#0b1016}.select:disabled{opacity:.55}.token{letter-spacing:.02em}
.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:14px}.btn{height:36px;border:1px solid var(--line2);background:#0c1117;color:#dce4ed;border-radius:5px;padding:0 12px;font:600 10px ui-monospace,SFMono-Regular,Menlo,monospace;cursor:pointer;text-decoration:none;white-space:nowrap;transition:background .15s,border-color .15s,transform .15s,box-shadow .15s}.btn:hover:not(:disabled){background:#131a23;border-color:#526174;transform:translateY(-1px);box-shadow:0 5px 14px rgba(0,0,0,.2)}.btn:active:not(:disabled){transform:none}.btn.primary{background:var(--blue);border-color:var(--blue);color:#06111e;box-shadow:0 5px 16px rgba(77,159,255,.16)}.btn.primary:hover:not(:disabled){background:#65acff;border-color:#65acff}.btn.danger{color:#ff8b93;border-color:#593039;background:#170d10}.btn.small{height:30px;padding:0 9px;font-size:9px}.btn:disabled{opacity:.4;cursor:not-allowed;transform:none}
.status{display:none;margin-top:13px;border:1px solid var(--line);border-radius:6px;padding:13px;background:#0c1117}.status.show{display:block;animation:panelIn .2s ease}#statusMsg{white-space:pre-line;overflow-wrap:anywhere}.status.ok{border-color:#255c43}.status.error{border-color:#653039}.status-title{font-size:11px;font-weight:700}.status-msg{font-size:9px;color:var(--muted);margin-top:3px;white-space:pre-wrap;word-break:break-word}.steps{display:grid;gap:5px;margin-top:11px;border-top:1px solid #202832;padding-top:9px}.step{color:#596676;font-size:9px;transition:color .2s}.step.active{color:#b9c7d7}.step.done{color:var(--green)}.dot{display:inline-block;width:6px;height:6px;border:1px solid #44505f;border-radius:50%;margin-right:7px}.step.active .dot{border-color:var(--blue);background:var(--blue);box-shadow:0 0 9px rgba(77,159,255,.7);animation:pulse 1s infinite}.step.done .dot{border-color:var(--green);background:var(--green)}
.result{margin-top:13px;border:1px solid #27583f;background:#0d1813;border-radius:6px;padding:13px;animation:panelIn .22s ease}.resultgrid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.resultitem{min-width:0;padding:10px;border:1px solid #26322f;border-radius:5px;background:#0a100e}.resultitem span{display:block;color:#718078;font-size:8px;text-transform:uppercase;letter-spacing:.05em;margin-bottom:3px}.resultitem strong{display:block;color:#dbe9e1;font:500 10px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;word-break:break-all}.deployments{display:grid;gap:7px}.deployment{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px;border:1px solid var(--line);border-radius:5px;background:#0c1117;transition:border-color .15s,background .15s}.deployment:hover{border-color:#435164;background:#0e141c}.deployment-main{min-width:0}.deployment-name{font:600 10px ui-monospace,SFMono-Regular,Menlo,monospace}.deployment-url{color:#6e7a89;font-size:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px}.footer{color:#596575;font-size:8px;text-align:center;margin-top:18px;line-height:1.7}.footer-links{display:flex;justify-content:center;gap:14px;margin-bottom:6px}.footer-links a{display:inline-flex;align-items:center;gap:5px;color:#7d8998;text-decoration:none}.footer-links a:hover{color:#dfe8f1}.footer-links svg{width:13px;height:13px}.hidden{display:none!important}
@keyframes panelIn{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:none}}@keyframes pulse{50%{opacity:.45;box-shadow:0 0 2px rgba(77,159,255,.2)}}
@media(max-width:650px){.wrap{width:calc(100% - 18px);padding:18px 0 28px}.top{padding:11px 12px}.state{display:none}.grid,.resultgrid{grid-template-columns:1fr}.full,.wide{grid-column:auto}.card{padding:15px}.actions .btn{flex:1}.actions .btn:only-child{flex:none}.deployment{align-items:flex-start;flex-direction:column}.deployment .row{width:100%}.deployment .row .btn{flex:1}}
</style></head><body><div class="wrap"><header class="top"><div class="brand"><div class="logo"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21.5 3.2 2.9 10.4c-.9.35-.88 1.62.03 1.94l4.65 1.63 1.74 5.5c.28.88 1.4 1.08 1.97.36l2.55-3.22 4.8 3.52c.78.57 1.9.15 2.1-.8l2.63-14.8c.17-.98-.75-1.68-1.87-1.33ZM9.15 13.42l8.98-5.66-7.07 7.1-.64 2.14-1.27 3.58Zm2.9 4.24.42-1.43 1.03-1.03 1.9 1.39-3.35 1.07Z"/></svg></div><div><h1>TWP-CF</h1><p>Telegram proxy deployment console</p></div></div><div class="pill">memory-only credentials</div></header><section class="hero"><h2>New deployment</h2><p>Deploy a complete Telegram web proxy panel directly to your Cloudflare account. Credentials are used only for the current request and are never persisted by this console.</p></section><section class="card"><div class="sectionhead"><strong>DEPLOYMENT CONFIGURATION</strong><span>Cloudflare</span></div><div class="grid"><div class="field full"><div class="label"><span>Cloudflare API Token</span><a class="hint link" href="https://dash.cloudflare.com/profile/api-tokens?permissionGroupKeys=%5B%7B%22key%22%3A%22workers_scripts%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22workers_kv_storage%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22d1%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22account_settings%22%2C%22type%22%3A%22read%22%7D%2C%7B%22key%22%3A%22workers_subdomain%22%2C%22type%22%3A%22edit%22%7D%2C%7B%22key%22%3A%22account_analytics%22%2C%22type%22%3A%22read%22%7D%5D&accountId=*&zoneId=all&name=TWP-CF-Deployer-Token" target="_blank" rel="noopener noreferrer">Create token</a></div><input id="token" class="input token" type="password" autocomplete="off" spellcheck="false" placeholder="Paste API token"></div><div class="field"><div class="label"><span>Account</span><span class="hint">verify first</span></div><select id="account" class="select" disabled><option value="">Verify token first</option></select></div><div class="field"><div class="label"><span>Worker name</span><span class="hint">optional</span></div><input id="name" class="input" maxlength="32" autocomplete="off" placeholder="Auto-generated if empty"></div><div class="field"><div class="label"><span>Proxy secret</span><span class="hint">32 hex · optional</span></div><input id="secret" class="input token" maxlength="34" autocomplete="off" placeholder="Generated securely if empty"></div></div><div class="actions"><button id="verify" class="btn">Verify access</button><button id="deploy" class="btn primary" disabled>Deploy</button><button id="reset" class="btn">Reset</button></div><div id="status" class="status"><div id="statusTitle" class="status-title"></div><div id="statusMsg" class="status-msg"></div><div id="steps" class="steps"><div class="step" data-step="verify"><i class="dot"></i>Verify account access</div><div class="step" data-step="package"><i class="dot"></i>Build proxy panel package</div><div class="step" data-step="upload"><i class="dot"></i>Upload panel and provision storage</div><div class="step" data-step="subdomain"><i class="dot"></i>Enable workers.dev</div></div></div><div id="result" class="result hidden"><div class="resultgrid"><div class="resultitem"><span>Worker</span><strong id="rName"></strong></div><div class="resultitem"><span>Proxy URL</span><strong id="rUrl"></strong></div><div class="resultitem"><span>Health</span><strong id="rHealth"></strong></div><div class="resultitem"><span>Secret</span><strong id="rSecret"></strong></div></div><div class="actions"><button class="btn small" id="copyUrl">Copy URL</button><button class="btn small" id="copySecret">Copy secret</button><button class="btn small" id="copyTelegram">Copy Telegram link</button><button class="btn small" id="openTelegram">Open in Telegram</button><button class="btn small" id="openUrl">Open panel</button></div><div class="resultitem" style="margin-top:10px"><span>Telegram web proxy</span><strong id="rTelegram"></strong></div></div></section><section id="managed" class="card hidden"><div class="sectionhead"><strong>MANAGED DEPLOYMENTS</strong><span>TWP-CF</span></div><div class="label"><span>Managed TWP-CF proxy panels</span><button id="refresh" class="btn small">Refresh</button></div><div id="list" class="deployments"></div></section><div class="footer"><div class="footer-links"><a href="https://github.com/ArasTey" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2C6.48 2 2 6.58 2 12.24c0 4.52 2.87 8.35 6.84 9.7.5.1.68-.23.68-.49v-1.72c-2.78.62-3.37-1.2-3.37-1.2-.46-1.2-1.12-1.52-1.12-1.52-.91-.64.07-.63.07-.63 1 .08 1.53 1.06 1.53 1.06.9 1.59 2.36 1.13 2.94.86.09-.67.35-1.13.64-1.39-2.22-.26-4.56-1.15-4.56-5.08 0-1.12.39-2.03 1.03-2.75 0-.26-.45-1.3.1-2.71 0 0 .84-.28 2.75 1.05A9.2 9.2 0 0 1 12 7.85c.85 0 1.7.12 2.5.37 1.9-1.33 2.74-1.05 2.74-1.05.55 1.41.2 2.45.1 2.71.64.72 1.03 1.63 1.03 2.75 0 3.94-2.35 4.81-4.59 5.07.36.32.68.94.68 1.9v2.82c0 .27.18.6.69.49A10.25 10.25 0 0 0 22 12.24C22 6.58 17.52 2 12 2Z"/></svg>GitHub</a><a href="https://t.me/imArasTey" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M21.5 3.2 2.9 10.4c-.9.35-.88 1.62.03 1.94l4.65 1.63 1.74 5.5c.28.88 1.4 1.08 1.97.36l2.55-3.22 4.8 3.52c.78.57 1.9.15 2.1-.8l2.63-14.8c.17-.98-.75-1.68-1.87-1.33ZM9.15 13.42l8.98-5.66-7.07 7.1-.64 2.14-1.27 3.58Zm2.9 4.24.42-1.43 1.03-1.03 1.9 1.39-3.35 1.07Z"/></svg>Telegram</a></div>TWP-CF deploys the proxy panel and runtime as one Cloudflare Worker.</div></div><script>
const $=s=>document.querySelector(s);const token=$('#token'),accountSelect=$('#account'),name=$('#name'),secret=$('#secret'),verify=$('#verify'),deploy=$('#deploy'),reset=$('#reset'),status=$('#status'),statusTitle=$('#statusTitle'),statusMsg=$('#statusMsg'),result=$('#result');let sessionToken='',account=null,accounts=[],last=null;
function generatedName(){return 'twp-cf-'+crypto.randomUUID().replaceAll('-','').slice(0,12)}
function generatedSecret(){const b=crypto.getRandomValues(new Uint8Array(16));return [...b].map(x=>x.toString(16).padStart(2,'0')).join('')}
function ensureDefaults(){if(!name.value.trim())name.value=generatedName();if(!secret.value.trim())secret.value=generatedSecret()}
function msg(title,text,type=''){status.className='status show '+type;statusTitle.textContent=title;statusMsg.textContent=text||''}function step(n,state='active'){document.querySelectorAll('.step').forEach(x=>{x.classList.remove('active','done');if(x.dataset.step===n)x.classList.add(state)})}function clearSteps(){document.querySelectorAll('.step').forEach(x=>x.classList.remove('active','done'))}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function explainError(error){const status=Number(error?.status||error?.cloudflare_status||0);const raw=String(error?.message||error||'Unknown error');const code=String(error?.code||'');const text=(raw+' '+code).toLowerCase();let title='Request failed',fix='Check the details and try again.';if(/invalid.*token|token.*invalid|authentication|unauthorized|401/.test(text)||status===401){title='API token is invalid or expired';fix='Create a new Cloudflare API token, ensure it is active, paste it again, then press Verify access.'}else if(/forbidden|permission|not authorized|access denied|403/.test(text)||status===403){title='Token permissions are insufficient';fix='Ensure the token has Workers Scripts Edit and required account access for the selected account. Recreate the token with the permissions shown by the Create token link.'}else if(/account.*not accessible|no accessible.*account|account.*not found/.test(text)){title='Selected account is not accessible';fix='Choose an account included in this token. If the expected account is missing, update the token account scope or ask the account owner to grant access.'}else if(/10063|workers.dev domain is not ready/.test(text)){title='Account workers.dev setup failed';fix='The deployer tries to create the account-level workers.dev subdomain before uploading the Worker. Cloudflare rejected that setup request, so no new Worker was uploaded. Check that the API token has Workers Scripts Edit permission and access to this account. If the account has never initialized Workers, open Workers & Pages once in the Cloudflare Dashboard, finish the workers.dev setup, then retry.'}else if(/workers_dev|workers.dev|subdomain/.test(text)){title='workers.dev domain is not ready';fix='The deployer checks or initializes the account-level workers.dev subdomain before uploading. Check the token permissions and account access; if Cloudflare has not initialized Workers for this account, open Workers & Pages once and retry.'}else if(/already exists|already in use|duplicate|script.*exists/.test(text)||status===409){title='Worker name is already in use';fix='Choose a different Worker name. Names must be unique within the Cloudflare account.'}else if(/durable object|durable_object|sqlite|migration|namespace/.test(text)){title='Durable Object provisioning failed';fix='Check Workers and Durable Objects availability, account limits, and token permissions. If a partial Worker exists, retry with a different name.'}else if(/limit|quota|too many|rate limit|429/.test(text)||status===429){title='Cloudflare rate or resource limit';fix='Wait a few minutes and retry. If Cloudflare reports a resource limit, review Workers usage and account limits.'}else if(/billing|payment|plan|not entitled/.test(text)){title='Account plan or billing restriction';fix='Review Billing and Workers settings for this account and resolve the restriction reported by Cloudflare.'}else if(/invalid.*name|worker name/.test(text)){title='Worker name is invalid';fix='Use a short name with letters, numbers, and hyphens only.'}else if(/failed to fetch|networkerror|load failed/.test(text)){title='Network request failed';fix='Check your connection and whether Cloudflare API access is reachable, then retry.'}return {title,detail:raw,fix,status,code}}
async function api(path,opts={}){const h=new Headers(opts.headers||{});if(sessionToken)h.set('Authorization','Bearer '+sessionToken);const r=await fetch(path,{...opts,headers:h,cache:'no-store',credentials:'same-origin'});let d=null;try{d=await r.json()}catch{}if(!r.ok||d?.success===false){const e=new Error(d?.error||d?.message||('Request failed (HTTP '+r.status+')'));e.status=r.status;e.code=d?.cloudflare_errors?.map(x=>x?.code).filter(Boolean).join(',')||'';e.cloudflare_status=d?.cloudflare_status||null;throw e}return d}
ensureDefaults();
verify.onclick=async()=>{const t=token.value.trim();if(!t)return msg('Token required','Paste a Cloudflare API token first.','error');verify.disabled=true;deploy.disabled=true;accountSelect.disabled=true;clearSteps();step('verify');msg('Verifying','Checking token and account access…');try{const d=await api('/api/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:t})});sessionToken=t;accounts=d.accounts||[];account=accounts.find(a=>a.id===d.account?.id)||accounts[0]||null;accountSelect.innerHTML=accounts.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.name)+' ('+esc(a.id.slice(0,8))+'...)</option>').join('');accountSelect.value=account?.id||'';accountSelect.disabled=accounts.length<2;deploy.disabled=!account;step('verify','done');msg('Connected',account.name+' ('+account.id+') is ready for deployment.','ok')}catch(e){sessionToken='';account=null;accounts=[];accountSelect.innerHTML='<option value="">Verify token first</option>';accountSelect.disabled=true;{const x=explainError(e);msg(x.title,x.detail+'\\n\\nWhat to do: '+x.fix+(x.status?'\\nHTTP status: '+x.status:'')+(x.code?'\\nCloudflare code: '+x.code:''),'error')}}finally{verify.disabled=false}};accountSelect.onchange=()=>{account=accounts.find(a=>a.id===accountSelect.value)||null;deploy.disabled=!sessionToken||!account};
deploy.onclick=async()=>{if(!sessionToken)return msg('Verify first','Verify the token before deploying.','error');
ensureDefaults();
const rawName=name.value.trim();
const normalizedName=rawName.toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/-+/g,'-').replace(/^-+|-+$/g,'');
if(!normalizedName){name.value=generatedName()}else{name.value=normalizedName.startsWith('twp-cf-')?normalizedName:'twp-cf-'+normalizedName}
const rawSecret=secret.value.trim().toLowerCase();
if(!rawSecret){secret.value=generatedSecret()}else if(!/^(?:[0-9a-f]{32}|dd[0-9a-f]{32})$/.test(rawSecret)){return msg('Invalid proxy secret','Use exactly 32 hexadecimal characters, optionally prefixed with dd, or leave it empty for automatic generation.','error')}else{secret.value=rawSecret}
deploy.disabled=true;verify.disabled=true;result.classList.add('hidden');try{step('package');msg('Preparing','Generating the deployment package…');await new Promise(r=>setTimeout(r,120));step('package','done');step('upload');msg('Deploying','Uploading the panel and provisioning the SQLite Durable Object namespace…');const d=await api('/api/deploy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:account?.id||'',name:name.value.trim(),secret:secret.value.trim()})});step('upload','done');step('subdomain');msg('Finalizing','Enabling workers.dev and checking the deployment…');await new Promise(r=>setTimeout(r,120));step('subdomain','done');last=d;$('#rName').textContent=d.name;$('#rUrl').textContent=d.url;$('#rHealth').textContent=d.health;$('#rSecret').textContent=d.secret;$('#rTelegram').textContent=d.telegramUrl;result.classList.remove('hidden');msg('Deployment complete',d.url,'ok');loadList()}catch(e){{const x=explainError(e);msg(x.title,x.detail+'\\n\\nWhat to do: '+x.fix+(x.status?'\\nHTTP status: '+x.status:'')+(x.code?'\\nCloudflare code: '+x.code:''),'error')}}finally{deploy.disabled=false;verify.disabled=false}};
async function copyValue(value,button){if(!value)return;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value)}else{const area=document.createElement('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}const old=button.textContent;button.textContent='Copied';setTimeout(()=>button.textContent=old,900)}catch{msg('Copy failed','Your browser blocked clipboard access. Select the value manually.','error')}}$('#copyUrl').onclick=()=>copyValue(last?.url,$('#copyUrl'));$('#copySecret').onclick=()=>copyValue(last?.secret,$('#copySecret'));$('#copyTelegram').onclick=()=>copyValue(last?.telegramUrl,$('#copyTelegram'));$('#openTelegram').onclick=()=>last?.telegramUrl&&window.open(last.telegramUrl,'_blank','noopener,noreferrer');$('#openUrl').onclick=()=>last?.url&&window.open(last.url,'_blank','noopener,noreferrer');reset.onclick=()=>{token.value='';name.value='';secret.value='';accountSelect.innerHTML='<option value="">Verify token first</option>';accountSelect.disabled=true;sessionToken='';account=null;accounts=[];last=null;deploy.disabled=true;result.classList.add('hidden');status.className='status';clearSteps();$('#managed').classList.add('hidden');setTimeout(ensureDefaults,0)};
async function loadList(){if(!sessionToken)return;try{const d=await api('/api/workers?accountId='+encodeURIComponent(account?.id||''));const arr=d.workers||[];$('#managed').classList.remove('hidden');$('#list').innerHTML=arr.length?arr.map(w=>\`<div class="deployment"><div class="deployment-main"><div class="deployment-name">\${esc(w.name)}</div><div class="deployment-url">\${esc(w.url)}</div></div><div class="row"><button class="btn small" onclick="open('\${w.url}')">Open</button><button class="btn small danger" onclick="removeWorker('\${w.name}')">Delete</button></div></div>\`).join(''):'<div class="hint">No managed workers found.</div>'}catch{}}window.removeWorker=async n=>{if(!confirm(\`Delete \${n}? This permanently removes the Worker and its Durable Object namespace.\`))return;try{await api('/api/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accountId:account?.id||'',name:n})});loadList()}catch(e){const x=explainError(e);msg('Delete failed: '+x.title,x.detail+'\\n\\nWhat to do: '+x.fix,'error')}};$('#refresh').onclick=loadList;
</script></body></html>`;
const DEPLOYER_VERSION = "2026.10.08";
const DEFAULT_COMPATIBILITY_DATE = "2026-10-08";

export default { async fetch(request, env, ctx) { return handle(request, env, ctx); } };

async function handle(request, env, ctx) {
  const u = new URL(request.url);
  if (request.method === "GET" && u.pathname === "/") {
    return new Response(HTML, { headers: headers("text/html; charset=utf-8") });
  }
  try {
    if (u.pathname === "/api/verify" && request.method === "POST") return await verify(request);
    if (u.pathname === "/api/deploy" && request.method === "POST") return await deploy(request);
    if (u.pathname === "/api/workers" && request.method === "GET") return await listWorkers(request);
    if (u.pathname === "/api/delete" && request.method === "POST") return await deleteWorker(request);
    return json({ success: false, error: "Not found" }, 404);
  } catch (e) {
    console.error("TWP-CF deployer error", e);
    const status = Number.isInteger(e?.cloudflareStatus) ? 502 : 400;
    return json({
      success: false,
      error: safe(e),
      cloudflare_status: e?.cloudflareStatus || null,
      cloudflare_errors: e?.cloudflareErrors || []
    }, status);
  }
}

function headers(type) {
  return {
    "Content-Type": type,
    "Cache-Control": "no-store, max-age=0",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    "Content-Security-Policy": "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'"
  };
}
function json(x, status=200) { return new Response(JSON.stringify(x), { status, headers: headers("application/json; charset=utf-8") }); }
function safe(e) { return e instanceof Error ? e.message : String(e); }

function tokenFrom(request) {
  const v = request.headers.get("Authorization") || "";
  if (!v.startsWith("Bearer ")) throw new Error("Cloudflare API token is required");
  const token = v.slice(7).trim();
  if (token.length < 20 || token.length > 512) throw new Error("Invalid Cloudflare API token format");
  return token;
}

async function cf(path, token, opts={}) {
  const h = new Headers(opts.headers || {});
  h.set("Authorization", "Bearer " + token);
  h.set("Accept", "application/json");
  const r = await fetch(CF_API + path, { ...opts, headers: h });
  let d = null;
  try { d = await r.json(); } catch {}
  if (!r.ok || d?.success === false) {
    const err = new Error(cloudflareError(d, `Cloudflare API request failed (HTTP ${r.status})`));
    err.cloudflareStatus = r.status;
    err.cloudflareErrors = Array.isArray(d?.errors) ? d.errors : [];
    throw err;
  }
  return d;
}

function cloudflareError(data, fallback) {
  const errors = Array.isArray(data?.errors) ? data.errors : [];
  const raw = errors.map(e => [e?.message, e?.code ? `code ${e.code}` : ''].filter(Boolean).join(' (') + (e?.code ? ')' : '')).filter(Boolean).join(' | ') || (data?.message ? String(data.message) : fallback);
  const message = raw.toLowerCase(); let hint = '';
  if (/token|unauthorized|authentication/.test(message)) hint = ' Check that the API token is active and correctly pasted.';
  else if (/permission|forbidden|not authorized/.test(message)) hint = ' The token may lack required permissions or may not include this account.';
  else if (/account/.test(message) && /access|permission|not found/.test(message)) hint = ' Select an account included in the token scope, or update the token account resources.';
  else if (/workers.dev|subdomain/.test(message)) hint = ' Enable the workers.dev subdomain in Workers & Pages for this account.';
  else if (/durable object|sqlite|namespace/.test(message)) hint = ' Check Durable Objects availability, account limits, and Workers edit permissions.';
  else if (/limit|quota|rate/.test(message)) hint = ' Check Workers usage/limits or wait before retrying.';
  return raw + hint;
}

async function verify(request) {
  const body = await request.json().catch(() => ({}));
  const token = String(body.token || "").trim();
  if (token.length < 20 || token.length > 512) throw new Error("Invalid API token format");

  const verified = await cf("/user/tokens/verify", token);
  if (verified?.result?.status !== "active") {
    throw new Error(`Token status: ${verified?.result?.status || "unknown"}`);
  }

  const accounts = await cf("/accounts?per_page=50&page=1", token);
  const list = Array.isArray(accounts?.result) ? accounts.result : [];
  if (!list.length) throw new Error("The token has no accessible Cloudflare accounts");

  const selected = body.accountId ? list.find(a => a.id === body.accountId) : list[0];
  if (!selected) throw new Error("Selected Cloudflare account is not accessible");

  return json({
    success: true,
    account: { id: selected.id, name: selected.name || selected.id },
    accounts: list.map(a => ({ id: a.id, name: a.name || a.id }))
  });
}

function workerName(input) {
  let value = String(input || "").trim().toLowerCase();
  if (!value) return "twp-cf-" + crypto.randomUUID().replaceAll("-", "").slice(0, 20);

  // The UI accepts a friendly custom name; users do not need to know the
  // internal TWP-CF prefix. Normalize it to a Cloudflare-safe worker name.
  value = value.replace(/[^a-z0-9-]+/g, "-").replace(/-+/g, "-").replace(/^-+|-+$/g, "");
  if (!value) throw new Error("Worker name contains no usable letters or numbers");
  if (!value.startsWith("twp-cf-")) value = "twp-cf-" + value;
  value = value.slice(0, 32).replace(/-+$/g, "");
  if (!/^twp-cf-[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value)) {
    throw new Error("Worker name must contain only letters, numbers and hyphens");
  }
  return value;
}

function randomSecret() {
  const b = crypto.getRandomValues(new Uint8Array(16));
  let s = "";
  for (const x of b) s += x.toString(16).padStart(2, "0");
  return s;
}

async function deploy(request) {
  const token = tokenFrom(request);
  const body = await request.json().catch(() => ({}));
  const accountId = String(body.accountId || "").trim();
  const name = workerName(String(body.name || "").trim());
  const secret = (String(body.secret || "").trim() || randomSecret()).toLowerCase();
  if (!accountId) throw new Error("Cloudflare account was not selected");
  if (!/^(?:[0-9a-f]{32}|dd[0-9a-f]{32})$/.test(secret)) throw new Error("Proxy secret must be 32 hex characters, optionally prefixed with dd");

  // Validate the account again with the supplied token. This prevents a stale/mismatched UI state.
  const accounts = await cf("/accounts?per_page=50&page=1", token);
  const account = (accounts.result || []).find(a => a.id === accountId);
  if (!account) throw new Error("The selected Cloudflare account is not accessible with this token");

  // Initialize the ACCOUNT-level workers.dev subdomain before uploading any Worker.
  // A brand-new account may not have one yet; uploading first can fail with Cloudflare
  // error 10063. Creating the account subdomain is supported by the Workers API.
  let accountSubdomain = null;
  try {
    const current = await cf(`/accounts/${encodeURIComponent(accountId)}/workers/subdomain`, token);
    accountSubdomain = current?.result?.subdomain || null;
  } catch {
    // A missing/uninitialized subdomain can make the GET fail. Try creating it below;
    // if creation also fails, surface Cloudflare's original error before uploading.
  }

  if (!accountSubdomain) {
    let createError = null;
    for (let attempt = 0; attempt < 3 && !accountSubdomain; attempt++) {
      const candidate = "twp-cf-" + crypto.randomUUID().replaceAll("-", "").slice(0, 10);
      try {
        const created = await cf(`/accounts/${encodeURIComponent(accountId)}/workers/subdomain`, token, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ subdomain: candidate })
        });
        accountSubdomain = created?.result?.subdomain || candidate;
      } catch (error) {
        createError = error;
        const messages = (error?.cloudflareErrors || []).map(item => String(item?.message || "")).join(" ").toLowerCase();
        const retryableConflict = error?.cloudflareStatus === 409 || /already exists|already in use|taken|duplicate|subdomain.*exist|exist.*subdomain/.test(messages);
        if (!retryableConflict) break;
      }
    }
    if (!accountSubdomain) {
      // Keep Cloudflare status/error codes intact for the UI diagnostics.
      if (createError) throw createError;
      throw new Error("Cloudflare did not return an account workers.dev subdomain. No Worker was uploaded.");
    }
  }

  const files = { ...RUNTIME };
  const metadata = {
    main_module: "index.js",
    compatibility_date: DEFAULT_COMPATIBILITY_DATE,
    bindings: [
      { name: "SESSIONS", type: "durable_object_namespace", class_name: "WebProxySession" },
      { name: "PROXY_SECRET", type: "secret_text", text: secret }
    ],
    exports: {
      WebProxySession: { type: "durable-object", storage: "sqlite", state: "created" }
    },
    annotations: { "workers/message": "TWP-CF deployment" }
  };

  // Cloudflare may accept the account-level workers.dev subdomain change before
  // its deployment API is ready to use it. On a brand-new account, the first
  // script upload can temporarily return error 10063 even though provisioning
  // succeeded. Retry ONLY that transient readiness error; never mask unrelated
  // deployment failures. Rebuild FormData on each attempt so every request has
  // a fresh multipart body.
  const scriptPath = `/accounts/${encodeURIComponent(accountId)}/workers/scripts/${encodeURIComponent(name)}`;
  const isWorkersDevNotReady = error => {
    const errors = Array.isArray(error?.cloudflareErrors) ? error.cloudflareErrors : [];
    return errors.some(item => Number(item?.code) === 10063 || /workers\.dev domain is not ready|workers.dev.*not ready/i.test(String(item?.message || "")))
      || /workers\.dev domain is not ready|workers.dev.*not ready/i.test(String(error?.message || ""));
  };
  const uploadDelays = [1000, 2000, 3500, 5000];
  let uploadError = null;
  for (let attempt = 0; attempt <= uploadDelays.length; attempt++) {
    const form = new FormData();
    form.append("metadata", new Blob([JSON.stringify(metadata)], { type: "application/json" }), "metadata.json");
    for (const [fileName, code] of Object.entries(files)) {
      form.append(fileName, new Blob([code], { type: "application/javascript+module" }), fileName);
    }
    try {
      await cf(scriptPath, token, { method: "PUT", body: form });
      uploadError = null;
      break;
    } catch (error) {
      uploadError = error;
      if (!isWorkersDevNotReady(error) || attempt >= uploadDelays.length) throw error;
      await new Promise(resolve => setTimeout(resolve, uploadDelays[attempt]));
    }
  }
  if (uploadError) throw uploadError;

  // Enable this specific Worker on workers.dev.
  try {
    await cf(`/accounts/${encodeURIComponent(accountId)}/workers/scripts/${encodeURIComponent(name)}/subdomain`, token, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ enabled: true })
    });
  } catch (error) {
    try {
      await cf(`/accounts/${encodeURIComponent(accountId)}/workers/scripts/${encodeURIComponent(name)}`, token, { method: "DELETE" });
    } catch {}
    throw new Error(`Worker uploaded, but workers.dev activation failed: ${error.message}`);
  }

  const host = `${name}.${accountSubdomain}.workers.dev`;
  const url = `https://${host}`;
  const telegramUrl = `https://t.me/webproxy?server=${encodeURIComponent(host)}&secret=${encodeURIComponent(secret)}`;
  return json({ success: true, name, secret, url, telegramUrl, health: url + "/healthz", account: account.name || accountId, subdomain: accountSubdomain });
}

async function listWorkers(request) {
  const token = tokenFrom(request);
  const accountId = new URL(request.url).searchParams.get("accountId") || "";
  if (!accountId) throw new Error("Cloudflare account was not selected");
  const accounts = await cf("/accounts?per_page=50&page=1", token);
  const account = (accounts.result || []).find(a => a.id === accountId);
  if (!account) throw new Error("The selected Cloudflare account is not accessible");
  const d = await cf(`/accounts/${encodeURIComponent(accountId)}/workers/scripts`, token);
  let accountSubdomain = null;
  try {
    const sd = await cf(`/accounts/${encodeURIComponent(accountId)}/workers/subdomain`, token);
    accountSubdomain = sd?.result?.subdomain || null;
  } catch {}
  const workers = (d.result || []).filter(w => String(w.id || w.name || "").startsWith("twp-cf-")).map(w => {
    const name = w.id || w.name;
    return { name, url: accountSubdomain ? `https://${name}.${accountSubdomain}.workers.dev` : null };
  });
  return json({ success: true, workers });
}

async function deleteWorker(request) {
  const token = tokenFrom(request);
  const body = await request.json().catch(() => ({}));
  const accountId = String(body.accountId || "").trim();
  const name = String(body.name || "").trim();
  if (!accountId) throw new Error("Cloudflare account was not selected");
  if (!/^twp-cf-[a-z0-9-]+$/.test(name)) throw new Error("Only TWP-CF managed workers can be deleted");
  await cf(`/accounts/${encodeURIComponent(accountId)}/workers/scripts/${encodeURIComponent(name)}`, token, { method: "DELETE" });
  return json({ success: true, name });
}
